{
  "technical_and_design_decisions": [
    "Use Spring XD's existing module system to implement processor modules for Reactor and RxJava, following the pattern of the existing Spark module.",
    "Upgrade Reactor dependency to 2.0 RC1 in the parent build configuration and adapt internal code to API changes.",
    "For Redis aggregation, port previous Spring XD field-value counter specifications and use RedisTemplate to maintain counters, writing continuous aggregations during ingestion.",
    "Isolate Hadoop tests by creating a new dedicated subproject and removing Hadoop test dependencies from the DIRT project to fix Eclipse classpath generation.",
    "For YARN on EC2 acceptance tests, implement a minimal smoke test suite and integrate it into CI with scripted EC2 provisioning.",
    "HTTP source module will read an optional property (e.g., maxMessageSize) from servers.yml via Spring Boot relaxed binding, defaulting to 1MB, and configure HttpChunkAggregator accordingly.",
    "All estimates include coding, unit/integration testing, and necessary documentation for the single developer performing the work."
  ],
  "assumptions": [
    "U3 and U4 are duplicate requirements and will be implemented once, not twice.",
    "The previous implementation wiki (spring-xd) is accessible and provides sufficient detail to port specifications.",
    "A workday equals 8 productive hours of development effort.",
    "The developer has existing knowledge of Spring XD, Reactor, RxJava, Redis, YARN, and EC2; no training time is included.",
    "EC2 environment can be provisioned in CI for acceptance tests, and only simple XD feature verification is required as per the story.",
    "The current codebase builds and has a passing test suite before this increment."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Upgrade to Reactor 2.0 RC1",
      "activity_description": "Update dependency management to Reactor 2.0 RC1, refactor existing code for API changes, run test suite, and fix any breakages (U2).",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Reactor-based stream processor plugin",
      "activity_description": "Design and implement a plugin that allows a reactor processor module to specify only the processor class; explore and implement module option commands for additional configuration following Spark/RxJava patterns, including unit tests (U1).",
      "most_likely_effort": 5.0
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "RxJava-based processor module",
      "activity_description": "Implement a processor module type that leverages RxJava APIs for data computations within the stream pipeline, with integration tests (U7).",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Redis-based aggregation over field-value counters",
      "activity_description": "Port specs from previous implementation, identify gaps, implement Redis-backed aggregation that continuously writes counters during ingestion, and update reference documentation (U3/U4).",
      "most_likely_effort": 7.5
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Isolate Hadoop tests into separate project",
      "activity_description": "Create a new test project for Hadoop, move relevant tests, remove DIRT dependency on Hadoop tests, and fix Eclipse classpath generation (U5).",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Acceptance test coverage for XD + YARN on EC2",
      "activity_description": "Develop acceptance tests for basic XD features on YARN, automate execution on EC2 in the build cycle, including CI configuration and validation (U6).",
      "most_likely_effort": 6.0
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "HTTP source message size configurability",
      "activity_description": "Expose HttpChunkAggregator message size limit as an overridable property via servers.yml with default 1MB, implement binding and override mechanism, add tests and minor docs (U8).",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Final integration and regression testing",
      "activity_description": "Integrate all changes, run full build, perform regression tests across modules, verify documentation, and prepare release artifacts.",
      "most_likely_effort": 3.0
    }
  ],
  "reported_total": {
    "most_likely_effort": 33.5
  }
}

